// Private planners. The plan itself is encrypted (PBKDF2 + AES-GCM) and only opens with the right passphrase,
// so the link alone shows nothing. Opened planners are kept in this browser's localStorage like any other planner.
export const PRIVATE = [
  { id: "annika-dec-2026", title: "Annika's planner", salt: "eKzHas19ZOqDCgIxqoXzcg==", iv: "SzNGyw3H9VjjcDWK", data: "" },
  { id: "annika-plan1", title: "Annika's Plan 1 (2027–28)", file: "data/private/annika-plan1.json" },
  { id: "annika-plan2", title: "Annika's Plan 2 (2027–28)", file: "data/private/annika-plan2.json" },
  { id: "annika-plan3", title: "Annika's Plan 3 (2027–28)", file: "data/private/annika-plan3.json" },
  { id: "annika-plan4", title: "Annika's Plan 4 (2027–28)", file: "data/private/annika-plan4.json" },
  { id: "annika-dsa", title: "Annika's DSA planner", file: "data/private/annika-dsa.json" },
];

const bytes = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

export async function unlock(entry, passphrase) {
  if (!entry.data) entry = { ...entry, ...(await (await fetch(entry.file, { cache: "no-store" })).json()) };
  const km = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveKey"]);
  const key = await crypto.subtle.deriveKey({ name: "PBKDF2", salt: bytes(entry.salt), iterations: 200000, hash: "SHA-256" }, km, { name: "AES-GCM", length: 256 }, false, ["decrypt"]);
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes(entry.iv) }, key, bytes(entry.data));
  let bytesOut = new Uint8Array(plain);
  if (entry.z) bytesOut = new Uint8Array(await new Response(new Blob([bytesOut]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).arrayBuffer());
  return JSON.parse(new TextDecoder().decode(bytesOut));
}
